import java.util.*;public final class CollectionsWorkload{public static void main(String[]z){var m=new HashMap<String,Long>();var a=new ArrayList<Long>();for(long i=0;i<10000;i++){m.put("k"+(i&4095),i);a.add(i);}long s=0;for(long i=0;i<4096;i++){var k="k"+i;s+=m.get(k);if((i&1)==0)s+=m.remove(k);}for(long v:a)s+=v;while(a.size()>5000)s+=a.remove(a.size()-1);System.out.println(s);}}
